def find_sep(g):
    h,w=len(g),len(g[0])
    allvals=set(x for r in g for x in r)
    for j in range(w):
        col={r[j] for r in g}
        if len(col)==1 and col.pop() not in (allvals-{g[0][j]}):
            pass
        if len(col)==1:
            c=g[0][j]
            others=set(x for i,r in enumerate(g) for k,x in enumerate(r) if k!=j)
            if c not in others:
                return j
for name,g in [('d1',demo1_in),('d2',d2_in),('t',test)]:
    print(name, find_sep(g))

def find_sep(g):
    h,w=len(g),len(g[0])
    for j in range(w):
        c=g[0][j]
        if all(r[j]==c for r in g):
            others={x for i,r in enumerate(g) for k,x in enumerate(r) if k!=j}
            if c not in others:
                return j
for name,g in [('d1',demo1_in),('d2',d2_in),('t',test)]:
    s=find_sep(g); print(name, s, g[0][s])

def transform(g):
    s=find_sep(g)
    h=len(g); wr=len(g[0])-(s+1)
    left=[r[:s] for r in g]; right=[r[s+1:] for r in g]
    ls={x for r in left for x in r}; rs={x for r in right for x in r}
    p=list(ls&rs)[0]
    return [[3 if (left[i][j]==p and right[i][j]==p) else p for j in range(wr)] for i in range(h)]

